class Solution:
    def first_missing_positive(self, nums: List[int]) -> int:
        n = len(nums)

        # Mark all negative numbers and zeros as non-positive
        for num in nums:
            if num <= 0 or num == 0:
                continue
            elif num > n:
                return 1

        # Find the first index where the number is out of range
        for i in range(n):
            if nums[i] >= n:
                return i + 1

        # If no gaps are found, the next number will be the answer
        return n + 1

